"""Generate immutable mHC CUDA regression values using original operators."""
from pathlib import Path
import torch,numpy as np,json,hashlib,inspect,argparse
from vllm.model_executor.kernels.mhc.tilelang import _hc_prenorm_gemm_outputs,mhc_pre_tilelang,mhc_post_tilelang
from vllm.model_executor.kernels.mhc.tilelang_kernels import mhc_pre_big_fuse_tilelang
parser=argparse.ArgumentParser();parser.add_argument('--header',type=Path,required=True);parser.add_argument('--metadata',type=Path,required=True);args=parser.parse_args()
d=4096;i=torch.arange(4*d,dtype=torch.int64);j=torch.arange(d,dtype=torch.int64);k=torch.arange(24*4*d,dtype=torch.int64).reshape(24,4*d)
r=(((i*17+13)%257-128).float()*2**-5).bfloat16().reshape(1,4,d).cuda();branch=(((j*29+3)%257-128).float()*2**-6).bfloat16().reshape(1,d).cuda();row=torch.arange(24,dtype=torch.int64)[:,None];col=torch.arange(4*d,dtype=torch.int64)[None,:];fn=(((row*65537+col*31337+19)%65521-32760).float()*2**-20).cuda();scale=torch.tensor([.3,-.7,1.2],device='cuda');base=(((torch.arange(24,dtype=torch.int64)*7)%31-15).float()*2**-4).cuda();norm=(1+((j*11)%33-16).float()*2**-7).bfloat16().cuda()
def run():
 dot,sq=_hc_prenorm_gemm_outputs(r.flatten(1),fn,hidden_size=d,hc_mult=4);assert dot.shape==(64,1,24)
 post,comb,x=mhc_pre_tilelang(r,fn,scale,base,1e-5,1e-6,1e-6,2.,20)
 _,_,normalized=mhc_pre_tilelang(r,fn,scale,base,1e-5,1e-6,1e-6,2.,20,norm_weight=norm,norm_eps=1e-5)
 pre=torch.empty((1,4),device='cuda');po=torch.empty_like(post);co=torch.empty_like(comb)
 mhc_pre_big_fuse_tilelang(dot,sq,scale,base,r,po.reshape(1,4),co.reshape(1,16),torch.empty_like(x),torch.zeros_like(pre),pre,torch.empty_like(x),hidden_size=d,rms_eps=1e-5,hc_pre_eps=1e-6,hc_sinkhorn_eps=1e-6,hc_post_mult_value=2.,sinkhorn_repeat=20,n_splits=64,hc_mult=4,save_pre_mix=True)
 assert torch.equal(po,post)and torch.equal(co,comb)
 return dict(dot=dot,sq=sq,pre=pre,post=post,comb=comb,collapsed=x,normalized=normalized,out=mhc_post_tilelang(branch,r,post,comb))
a=run();b=run();assert all(torch.equal(a[k],b[k])for k in a)
text='/* Original vLLM SM120 mHC procedural fixture. Generated by reference_cuda_mhc.py. */\n#ifndef BN_CUDA_MHC_REFERENCE_H\n#define BN_CUDA_MHC_REFERENCE_H\n';hashes={}
for name,value in a.items():
 value=value.detach().contiguous().cpu();data=value.view(torch.uint8).numpy().tobytes();hashes[name]=hashlib.sha256(data).hexdigest();bf=value.dtype==torch.bfloat16;array=value.view(torch.uint16).numpy().reshape(-1)if bf else value.numpy().reshape(-1);text+=f'static const {"uint16_t"if bf else "float"} cuda_mhc_ref_{name}[{len(array)}] = {{\n'
 for start in range(0,len(array),8):text+='    '+', '.join(f'0x{int(x):04x}'if bf else float(x).hex()+'f'for x in array[start:start+8])+',\n'
 text+='};\n'
text+='#endif\n';args.header.write_text(text);args.metadata.write_text(json.dumps({'dim':d,'tokens':1,'streams':4,'splits':64,'repeated_exact':True,'hashes':hashes,'sources':{str(q):hashlib.sha256(q.read_bytes()).hexdigest()for q in [Path(inspect.getfile(mhc_pre_tilelang)),Path(inspect.getfile(mhc_pre_tilelang)).with_name('tilelang_kernels.py')]},'header_sha256':hashlib.sha256(text.encode()).hexdigest()},indent=2)+'\n');print('Captured',sum(t.numel()for t in a.values()),'original output words',flush=True)
